// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        uint256 v = bound(uint256(amount), 1, 100 ether);
        uint256 before = __invmut_c_Acc_balance(actor);
        vm.deal(actor, v);
        vm.prank(actor);
        c.Put{value: v}(0);
        assertTrue(__invmut_c_Acc_balance(actor) == before + v);
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
